{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four category models, jointly reduce dropout to 0.2 and AdamW learning rate to 7e-4, while increasing weight decay to 1e-5. Lower dropout may retain more short-history signal; smaller updates and stronger weight decay may control overfitting. Preserve the HSTU architecture, features, tied embeddings, readout, loss, seeds and training limits. Existing checkpoint metadata and predictor loading remain compatible.",
      "edits": [
        {
          "find": "DROPOUT_RATE = float(os.environ.get(\"HSTU_DROPOUT\", \"0.3\"))",
          "replace": "DROPOUT_RATE = float(os.environ.get(\"HSTU_DROPOUT\", \"0.2\"))"
        },
        {
          "find": "LR = float(os.environ.get(\"HSTU_LR\", \"1e-3\"))",
          "replace": "LR = float(os.environ.get(\"HSTU_LR\", \"7e-4\"))"
        },
        {
          "find": "WEIGHT_DECAY = float(os.environ.get(\"HSTU_WD\", \"1e-6\"))",
          "replace": "WEIGHT_DECAY = float(os.environ.get(\"HSTU_WD\", \"1e-5\"))"
        },
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        }
      ]
    }
  ],
  "change_summary": "Apply the supplied coupled dropout, learning-rate and weight-decay mutation to all four independent HSTU category models, and enforce the required data-directory environment variable."
}
